mapper.select:
SELECT l.id, l.user_id, u.username, l.api_key_id, k.key_prefix, l.endpoint_path, m.name AS endpoint_name, l.http_status, l.cost_points, l.latency_ms, l.client_ip, l.create_time FROM api_access_log l LEFT JOIN sys_user u ON u.id = l.user_id LEFT JOIN api_key_info k ON k.id = l.api_key_id LEFT JOIN ( SELECT path, MIN(name) AS name FROM api_endpoint_meta GROUP BY path ) m ON m.path = l.endpoint_path WHERE l.create_time >= #{criteria.startTime} AND l.create_time <= #{criteria.endTime}
AND l.user_id = #{criteria.userId}
AND u.username LIKE CONCAT('%', #{criteria.username}, '%')
AND l.endpoint_path = #{criteria.endpointPath}
AND l.http_status = #{criteria.httpStatus}
AND l.latency_ms >= #{criteria.minLatencyMs}
ORDER BY l.create_time DESC, l.id DESC
